import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String s = br.readLine();String target = "hello";int targetIdx = 0;for (int i = 0; i < s.length(); i++) {if (targetIdx < target.length() && s.charAt(i) == target.charAt(targetIdx)) {targetIdx++;}}if (targetIdx == target.length()) {System.out.println("YES");} else {System.out.println("NO");}}}